from typing import Any
import numpy as np
import scipy.linalg


class Solver:
    def solve(self, problem, **kwargs) -> Any:
        A = np.asarray(problem["matrix"], dtype=complex)
        n = A.shape[0]

        # Fast path: eigendecomposition. The principal sqrt of a complex number
        # via numpy returns a value with non-negative real part, which matches
        # the principal-branch convention required here.
        try:
            w, V = np.linalg.eig(A)
            sqrt_w = np.sqrt(w)
            # Solve V @ Y = (V*sqrt_w) instead of explicit inverse for stability/speed
            X = np.linalg.solve(V.T, (V * sqrt_w).T).T

            # Quick correctness check
            recon = X @ X
            scale = max(1.0, np.max(np.abs(A)))
            err = np.max(np.abs(recon - A))
            if np.all(np.isfinite(X)) and err <= 1e-7 * scale:
                return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            pass

        # Robust fallback: scipy's Schur-based sqrtm
        try:
            X, _ = scipy.linalg.sqrtm(A, disp=False)
        except Exception:
            return {"sqrtm": {"X": []}}

        return {"sqrtm": {"X": X.tolist()}}

